do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Faith in the Fire: Daniel$j$, $j${"readings": [{"title": "Daniel 1 (King James Version)", "url": "/portal/bible/Daniel/1"}, {"title": "Daniel 3 (King James Version)", "url": "/portal/bible/Daniel/3"}, {"title": "Daniel 6 (King James Version)", "url": "/portal/bible/Daniel/6"}, {"title": "Daniel 7 (King James Version)", "url": "/portal/bible/Daniel/7"}], "body": "Read Daniel 1, Daniel 3, Daniel 6 and Daniel 7:13 and 14 in the King James Version. Then read this lesson.\n\nDaniel was taken to Babylon as a teenager and trained to serve in the king's court. He and his friends Shadrach, Meshach and Abednego refused to defile themselves with the king's food and later refused to bow to a golden image. The three friends were thrown into a fiery furnace and God delivered them. Daniel was thrown into the den of lions for praying to God, and God shut the lions' mouths. Daniel also interpreted dreams and received visions of kingdoms to come, which ended with the kingdom of God that will never be destroyed. Daniel is a book of courage for people living in a culture that does not follow God.\n\nKey words: faith, courage, integrity, kingdom, deliverance.\n\nYour task: (1) Name the three friends who were thrown into the furnace. (2) Tell why Daniel was thrown to the lions. (3) Say what Daniel 7:14 teaches about the kingdom of God.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The last of the major prophets is Daniel, and it is one of the most loved books in the Bible. It is a book about young people who stayed faithful to God in a foreign land.\n\nDaniel was probably a teenager when Babylon took him away from Jerusalem. The king chose Daniel and three other young men, Hananiah, Mishael and Azariah, to be trained for the king's service. They were given new names in Babylon. Daniel was called Belteshazzar and the three friends were called Shadrach, Meshach and Abednego. In chapter 1 we read that Daniel purposed in his heart that he would not defile himself with the king's food. He asked to eat vegetables and drink water, and God blessed him with health and wisdom.\n\nIn chapter 3 King Nebuchadnezzar set up a huge golden image and commanded everyone to bow down. Shadrach, Meshach and Abednego refused. They told the king that the God they served was able to deliver them, and that even if He did not, they would not worship the image. The king had them thrown into a furnace heated seven times hotter than normal. But the king saw four men walking in the fire, and the fourth looked like the Son of God. They came out without even the smell of smoke on them.\n\nDaniel stayed in service under later kings. In chapter 6, under King Darius, jealous officials tricked the king into signing a law that no one could pray to anyone except the king for thirty days. Daniel knew the law was signed, and he went home and prayed three times a day with his windows open toward Jerusalem. He was thrown to the lions, but God sent an angel and shut the lions' mouths. In the morning the king found Daniel alive.\n\nDaniel also received visions of the future. In chapter 2 he interpreted a dream of a great statue that represented kingdoms of the world. In chapter 7 he saw one like the Son of man coming with the clouds of heaven. Daniel 7:14 says, And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed. Earthly empires rise and fall, but God's kingdom will last forever.\n\nYour task is to name the three friends, tell why Daniel was thrown to the lions, and explain what Daniel 7:14 teaches. Then take the four question check and the Unit 4 quiz.\n\nStand for what is right even when you stand alone. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Faith in the Fire: Daniel$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: A Prophet's Message$j$, $j${"prompt": "Choose one of the four prophets in this unit: Isaiah, Jeremiah, Ezekiel or Daniel. Write one paragraph of 150 to 200 words. Tell who the prophet was, what message God gave the prophet, and how the people responded. Then explain one lesson from the prophet's life that a student today can use. Quote at least one verse from the King James Version.", "rubric": "Total 100. Accurate account of the prophet and the message: 30. Describes how the people responded: 20. Explains one lesson for today, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: A Prophet's Message$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Standing for What Is Right$j$, $j${"prompt": "Daniel and his friends stood firm when everyone around them did otherwise. Describe a time you had to stand for what was right, or a time you wish you had. Explain what courage looks like for a student your age. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Standing for What Is Right$j$);
end
$seed$;
